sources.app.tsx:
// A web browser on the frame's screen. Type an address (or words to search
// for), and the page is downloaded, cleaned and drawn as JSX: html.ts reads
// the HTML in one pass and keeps the text, links, pictures, tables, lists and
// GET forms, with the colors and sizes its style sheets give them (css.ts);
// scripts, styles, frames, video and hidden parts are dropped. view.tsx draws
// what is left, and a tap on a link opens it here. Hold a link for its menu:
// open it, or show its QR code to open it on a phone.
//
// The page downloads with frameos.useFetch: off the render where the frame
// pumps promises (a tap answers at once and the page follows), in the render
// where it does not (e-paper: one refresh with the page). Back and forward are
// the toolbar's arrows and the frame's own back / forward (a HyperPixel's edge
// swipes, a reTerminal's keys). Where you have been is kept with
// frameos.remember, so a frame that let the interpreter go opens on the same
// page, scrolled where it was. Built and tested against Hacker News.

import { convert, scanHead, type Page } from './html'
import { MAX_SVG_TEXT, parseSvg, type SvgEl } from './svg'
import { jsxSource, renderPage, type Act } from './view'

const HOME = 'https://news.ycombinator.com/'
const SEARCH = 'https://lite.duckduckgo.com/lite/?q='
const MAX_HISTORY = 40
const MAX_HTML = 1536 * 1024
const MAX_CSS = 256 * 1024
const HEADERS = {
  'User-Agent': 'Mozilla/5.0 (compatible; FrameOS browser)',
  Accept: 'text/html,application/xhtml+xml,text/plain;q=0.9,*/*;q=0.5',
}
const ZOOMS = [0.6, 0.7, 0.8, 0.9, 1, 1.15, 1.3, 1.5, 1.75, 2]

// frameos.useFetch is experimental (docs/async-js.md): the editor's
// declarations do not have it yet.
const useFetch = (url: string, init: Record<string, any>) => (frameos as any).useFetch(url, init)

type Entry = { u: string; y: number }
type Nav = { list: Entry[]; at: number }
type Load = { url: string; n: number; html?: string; status?: number; sheets?: string[] }

let page: Page | null = null // the page showing
let loading: Load | null = null
let loadSeq = 0
let failure: { url: string; why: string } | null = null
let typed: string | null = null // the address while it is being typed
let held = '' // the link whose menu is open
let source = false // the page as JSX
let scrollY = 0 // where the page is scrolled to (UI pixels)
let scrollAttr = 0 // what the page box is told: changed only to move it
let rev = 0 // the fields' values changed
const pages = new Map<string, Page>() // pages seen, newest last
const sheets = new Map<string, string>() // style sheets by URL
const values = new Map<string, string>() // what was typed into a page's fields
const svgs = new Map<string, SvgEl | null>() // SVG pictures by URL, read (null: not one)

const kept = (key: string, empty: any) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

function readNav(app: any): Nav {
  const nav = kept('nav', null)
  if (nav && Array.isArray(nav.list) && nav.list.length) return nav
  return { list: [{ u: homeOf(app), y: 0 }], at: 0 }
}
const saveNav = (nav: Nav) => frameos.remember('nav', nav)
const homeOf = (app: any) => normalize(String(app.state.homepage || app.config.homepage || HOME)) || HOME

// What was typed as a URL: an address, or words to search for.
export function normalize(text: string): string {
  const t = text.trim()
  if (!t) return ''
  if (/^https?:\/\//i.test(t)) return t
  if (/^[\w-]+(\.[\w-]+)+(:\d+)?(\/\S*)?$/.test(t) || /^localhost(:\d+)?(\/|$)/.test(t)) return 'http' + (/^(localhost|\d+\.\d+\.\d+\.\d+)/.test(t) ? '' : 's') + '://' + t
  return SEARCH + encodeURIComponent(t)
}

// A search result's link is DuckDuckGo's redirect: the page it names instead.
function unwrap(url: string): string {
  const m = /^https?:\/\/(?:html\.|lite\.)?duckduckgo\.com\/l\/\?(?:.*&)?uddg=([^&]+)/.exec(url)
  if (m) {
    try {
      return decodeURIComponent(m[1])
    } catch (e) {
      return url
    }
  }
  return url
}

const appRef: { app: any } = { app: null }

// One app object is one browser: the interpreter's. A new one (a test's
// makeApp) starts with nothing open.
function bind(app: any) {
  if (appRef.app === app) return
  appRef.app = app
  page = null
  loading = null
  failure = null
  typed = null
  held = ''
  source = false
  scrollY = 0
  pages.clear()
  values.clear()
}

function jumpTo(y: number) {
  // scrollTop moves the box only when it changes (docs/jsx-ui.md): the same
  // place again is told a hair apart.
  scrollAttr = scrollAttr === y ? y + 0.01 : y
  scrollY = y
}

function open(url: string) {
  const app = appRef.app
  const nav = readNav(app)
  nav.list[nav.at].y = scrollY
  nav.list = nav.list.slice(0, nav.at + 1)
  nav.list.push({ u: unwrap(url), y: 0 })
  if (nav.list.length > MAX_HISTORY) nav.list = nav.list.slice(-MAX_HISTORY)
  nav.at = nav.list.length - 1
  saveNav(nav)
  typed = null
  held = ''
  source = false
  failure = null
}

function step(by: number): boolean {
  const nav = readNav(appRef.app)
  const at = nav.at + by
  if (at < 0 || at >= nav.list.length) return false
  nav.list[nav.at].y = scrollY
  nav.at = at
  saveNav(nav)
  typed = null
  held = ''
  failure = null
  return true
}

function reload() {
  const nav = readNav(appRef.app)
  pages.delete(nav.list[nav.at].u)
  nav.list[nav.at].y = scrollY
  saveNav(nav)
  page = null
  loading = null
  failure = null
}

function submit(form: number) {
  if (!page || !page.forms[form]) return
  const f = page.forms[form]
  const parts: string[] = []
  f.fields.forEach((field, i) => {
    if (field.type === 'submit') return
    const value = values.get(`${page!.url}|${form}|${i}`) ?? field.value
    parts.push(encodeURIComponent(field.name) + '=' + encodeURIComponent(value).replace(/%20/g, '+'))
  })
  open(f.action + (parts.length ? '?' + parts.join('&') : ''))
}

const act: Act = {
  go: (url) => open(url),
  hold: (url) => {
    held = url
  },
  value: (form, field) => {
    const key = `${page ? page.url : ''}|${form}|${field}`
    return values.get(key) ?? (page && page.forms[form] ? page.forms[form].fields[field].value : '')
  },
  type: (form, field, value) => {
    const at = value.indexOf('\n')
    values.set(`${page ? page.url : ''}|${form}|${field}`, at < 0 ? value : value.slice(0, at))
    rev++
    if (at >= 0) submit(form)
  },
  submit,
  svg: (url) => svgs.get(url) || null,
}

// A page from what was downloaded: HTML, plain text, or a picture.
function pageFrom(load: Load, embedded: boolean, viewport: number): Page {
  const html = load.html || ''
  const head = html.slice(0, 2048).trimStart().toLowerCase()
  const isHtml = head.startsWith('<') || /<(html|body|div|p|table|a|head)[\s>]/.test(head)
  const text = isHtml
    ? html
    : '<pre>' + html.slice(0, 200000).replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>'
  const css = (load.sheets || []).map((u) => sheets.get(u) || '')
  return convert(text, load.url, { sheets: css, sheetUrls: load.sheets, viewport, maxImages: embedded ? 12 : 40,
    maxRuns: embedded ? 8000 : 30000, maxSvg: embedded ? 1500 : 4000, maxSvgFiles: embedded ? 4 : 6 })
}

function imagePage(url: string): Page {
  return {
    url,
    title: url.slice(url.lastIndexOf('/') + 1),
    bg: '#202020',
    root: { k: 'b', c: [{ k: 't', align: 'center', pre: false, runs: [{ img: url, w: 0, h: 0, alt: '' }] }] },
    forms: [],
    svgs: [],
    truncated: false,
    stats: { runs: 1, images: 1, links: 0 },
  }
}

function remember(p: Page, embedded: boolean) {
  pages.delete(p.url)
  pages.set(p.url, p)
  while (pages.size > (embedded ? 1 : 4)) pages.delete(pages.keys().next().value as string)
}

// Moves the download of `url` along: the page, then its style sheets, then the
// page drawn. Returns the page once it is in.
function fetchPage(url: string, embedded: boolean, viewport: number): Page | null {
  if (!loading || loading.url !== url) loading = { url, n: ++loadSeq }
  const load = loading
  if (/\.(png|jpe?g|gif|webp|bmp|svg)(\?[^/]*)?$/i.test(url)) {
    loading = null
    return imagePage(url)
  }
  if (load.html === undefined) {
    const answer = useFetch(url, { as: 'text', headers: HEADERS, timeoutMs: 20000, n: load.n })
    if (answer.loading && answer.data === undefined) return null
    if (answer.error || (answer.data === undefined && !answer.ok)) {
      failure = { url, why: answer.error || `HTTP ${answer.status}` }
      loading = null
      return null
    }
    load.html = String(answer.data ?? '').slice(0, MAX_HTML)
    load.status = answer.status
    answer.data = '' // the text is drawn from here on: let it go
    load.sheets = scanHead(load.html, url).sheets
  }
  for (const sheet of load.sheets || []) {
    if (sheets.has(sheet)) continue
    const answer = useFetch(sheet, { as: 'text', headers: HEADERS, timeoutMs: 10000 })
    if (answer.loading && answer.data === undefined) return null
    sheets.set(sheet, answer.ok ? String(answer.data ?? '').slice(0, MAX_CSS) : '')
    answer.data = ''
    while (sheets.size > 8) sheets.delete(sheets.keys().next().value as string)
  }
  const p = pageFrom(load, embedded, viewport)
  loading = null
  return p
}

const PageView = memo((props: any) =>
  renderPage(props.page, props.width, { k: props.k, minPx: props.minPx, ink: props.ink }, act)
)

const SourceView = memo((props: any) => {
  const lines = jsxSource(props.page, { k: props.k, minPx: props.minPx, ink: props.ink }, 400)
  return (
    <div className={`flex flex-col p-[8px] bg-[#1e1e1e] text-[#d4d4d4] font-mono text-[${props.minPx + 1}px] leading-[${Math.round((props.minPx + 1) * 1.4)}px]`}>
      {lines.map((line: string) => {
        const indent = line.length - line.trimStart().length
        return (
          <div className="whitespace-nowrap truncate">
            {' '.repeat(indent) + line.trimStart()}
          </div>
        )
      })}
    </div>
  )
})

const ICONS = {
  back: 'M20,11V13H8L13.5,18.5L12.08,19.92L4.16,12L12.08,4.08L13.5,5.5L8,11H20Z',
  forward: 'M4,11V13H16L10.5,18.5L11.92,19.92L19.84,12L11.92,4.08L10.5,5.5L16,11H4Z',
  reload:
    'M17.65,6.35C16.2,4.9 14.21,4 12,4A8,8 0 0,0 4,12A8,8 0 0,0 12,20C15.73,20 18.84,17.45 19.73,14H17.65C16.83,16.33 14.61,18 12,18A6,6 0 0,1 6,12A6,6 0 0,1 12,6C13.66,6 15.14,6.69 16.22,7.78L13,11H20V4L17.65,6.35Z',
  stop: 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z',
  home: 'M10,20V14H14V20H19V12H22L12,3L2,12H5V20H10Z',
  code: 'M14.6,16.6L19.2,12L14.6,7.4L16,6L22,12L16,18L14.6,16.6M9.4,16.6L4.8,12L9.4,7.4L8,6L2,12L8,18L9.4,16.6Z',
  minus: 'M19,13H5V11H19V13Z',
  plus: 'M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z',
}

export function onEvent(app: any, context: any) {
  bind(app)
  if (context.event === 'back') return step(-1)
  if (context.event === 'forward') return step(1)
  return false
}

export function get(app: any, context: any) {
  bind(app)
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const embedded = app.frame.embedded === true
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // The chrome's size by the frame, as the Terminal sample's text: twice it on a
  // 4K screen or large e-paper, smaller under 480.
  const shortSide = Math.min(app.frame.width, app.frame.height)
  const z = shortSide >= (paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : Math.max(0.75, shortSide / 480)
  const zoomAt = Math.max(0, Math.min(ZOOMS.length - 1, Number(kept('zoom', 4))))
  const k = Math.round(z * 1.2 * ZOOMS[zoomAt] * 100) / 100
  const minPx = Math.round(10 * z * Math.min(1, ZOOMS[zoomAt] + 0.1))

  // A new home page in the scene's settings is opened.
  const home = homeOf(app)
  if (kept('home', '') !== home) {
    frameos.remember('home', home)
    if (kept('nav', null)) open(home)
  }

  const nav = readNav(app)
  const entry = nav.list[nav.at]
  if (!page || page.url !== entry.u) {
    const seen = pages.get(entry.u)
    if (seen) {
      page = seen
      jumpTo(entry.y)
    } else if (!failure || failure.url !== entry.u) {
      // The width it is laid out at, in CSS pixels, for its @media rules.
      const p = fetchPage(entry.u, embedded, Math.round((width - 4 * z) / k))
      if (p) {
        page = p
        remember(p, embedded)
        jumpTo(entry.y)
      }
    }
  }
  const showing = page && page.url === entry.u ? page : null
  // The page's SVG pictures, after it shows: each drawn when it is in.
  if (showing && !source) {
    for (const url of showing.svgs) {
      if (svgs.has(url)) continue
      const answer = useFetch(url, { as: 'text', headers: HEADERS, timeoutMs: 10000 })
      if (answer.loading && answer.data === undefined) continue
      svgs.set(url, answer.ok ? parseSvg(String(answer.data ?? '').slice(0, MAX_SVG_TEXT + 1)) : null)
      answer.data = ''
      rev++
      while (svgs.size > 24) svgs.delete(svgs.keys().next().value as string)
    }
  }
  const busy = !showing && !!loading
  const failed = !showing && failure && failure.url === entry.u ? failure.why : ''

  const bar = Math.round(38 * z)
  const icon = Math.round(20 * z)
  const text = Math.round(15 * z)
  const fg = ink ? 'text-[#000000]' : 'text-[#e8e8e8]'
  const button = (path: string, onClick: () => void, enabled = true) => (
    <div
      className={`flex items-center justify-center w-[${bar}px] h-[${bar}px] shrink-0 ${
        enabled ? (ink ? '' : 'active:bg-[#4a4a4a] hover:bg-[#3a3a3a]') : 'opacity-40'
      } cursor-pointer`}
      onClick={enabled ? onClick : () => {}}
    >
      <svg viewBox="0 0 24 24" className={`w-[${icon}px] h-[${icon}px]`}>
        <path d={path} fill="currentColor" />
      </svg>
    </div>
  )
  const address = typed ?? entry.u
  const contentW = width - Math.round(4 * z)

  return (
    <div className={`flex flex-col w-full h-full ${ink ? 'bg-[#ffffff]' : 'bg-[#ffffff]'}`}>
      <div
        className={`flex items-center h-[${bar}px] shrink-0 gap-[${Math.round(2 * z)}px] px-[${Math.round(2 * z)}px] ${
          ink ? 'bg-[#ffffff] border-b border-[#000000]' : 'bg-[#2b2b2b]'
        } ${fg}`}
      >
        {button(ICONS.back, () => step(-1), nav.at > 0)}
        {button(ICONS.forward, () => step(1), nav.at < nav.list.length - 1)}
        {button(busy ? ICONS.stop : ICONS.reload, () => {
          if (busy) {
            loading = null
            failure = { url: entry.u, why: 'Stopped' }
          } else reload()
        })}
        {button(ICONS.home, () => open(homeOf(app)))}
        <input
          className={`flex-1 min-w-0 h-[${bar - Math.round(10 * z)}px] px-[${Math.round(8 * z)}px] rounded-[${Math.round(4 * z)}px] text-[${text}px] ${
            ink ? 'border border-[#000000] text-[#000000] bg-[#ffffff]' : 'bg-[#1a1a1a] text-[#f0f0f0] focus:bg-[#000000]'
          }`}
          value={address}
          placeholder="Search or type an address"
          onChange={(e: any) => {
            typed = String(e.target.value)
          }}
          onKeyDown={(e: any) => {
            if (e.key === 'Enter') {
              const url = normalize(typed ?? address)
              if (url) open(url)
            } else if (e.key === 'Escape') typed = null
          }}
        />
        {button(ICONS.minus, () => frameos.remember('zoom', Math.max(0, zoomAt - 1)), zoomAt > 0)}
        {button(ICONS.plus, () => frameos.remember('zoom', Math.min(ZOOMS.length - 1, zoomAt + 1)), zoomAt < ZOOMS.length - 1)}
        {button(ICONS.code, () => {
          source = !source
          jumpTo(0)
        }, !!showing)}
      </div>
      <div
        className="flex flex-col flex-1 min-h-0 overflow-y-auto"
        scrollTop={scrollAttr}
        onScroll={(e: any) => {
          scrollY = e.scrollTop
        }}
      >
        {showing ? (
          source ? (
            <SourceView page={showing} k={k} minPx={minPx} ink={ink} />
          ) : (
            <PageView page={showing} width={contentW} k={k} minPx={minPx} ink={ink} rev={rev} />
          )
        ) : (
          <div className={`flex flex-col items-center justify-center flex-1 gap-[${Math.round(10 * z)}px] p-[${Math.round(16 * z)}px] text-[#555555] text-[${text}px]`}>
            {failed ? (
              <>
                <span className={`text-[${Math.round(text * 1.3)}px] text-[#222222] font-bold`}>This page did not load</span>
                <span className="text-center">{failed}</span>
                <span className="text-center text-[#888888]">{entry.u}</span>
                <div
                  className={`px-[${Math.round(14 * z)}px] py-[${Math.round(6 * z)}px] rounded border border-[#888888] text-[#222222] cursor-pointer`}
                  onClick={() => reload()}
                >
                  Try again
                </div>
              </>
            ) : (
              <>
                <span>{'Loading ' + (entry.u.replace(/^https?:\/\//, '').split('/')[0] || '') + '…'}</span>
              </>
            )}
          </div>
        )}
      </div>
      {held ? (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50" onClick={() => (held = '')}>
          <div
            className={`flex flex-col gap-[${Math.round(8 * z)}px] w-[${Math.min(width - 32, Math.round(440 * z))}px] p-[${Math.round(14 * z)}px] rounded-[${Math.round(8 * z)}px] bg-[#ffffff] text-[#111111] text-[${text}px] ${ink ? 'border-2 border-[#000000]' : ''}`}
            onClick={() => {}}
          >
            <span className={`text-[${Math.round(text * 0.85)}px] text-[#555555] line-clamp-3`}>{held}</span>
            <div className="flex gap-[8px]">
              <div
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded bg-[#ff6600] text-[#ffffff] font-bold cursor-pointer`}
                onClick={() => open(held)}
              >
                Open
              </div>
              <a
                href={held}
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded border border-[#888888] cursor-pointer`}
              >
                QR code
              </a>
              <div
                className={`flex-1 flex justify-center py-[${Math.round(8 * z)}px] rounded border border-[#888888] cursor-pointer`}
                onClick={() => (held = '')}
              >
                Cancel
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  )
}

sources.html.ts:
// HTML to a page this browser can draw, in one pass over the text: a forgiving
// tokenizer feeds a tree builder that keeps only what reads (text, links,
// pictures, tables, lists, headings, GET forms) and drops the rest (scripts,
// styles, frames, video, inline SVG, hidden parts, POST forms). The builder
// never holds the document as a DOM: it keeps a stack of the open elements,
// for the cascade (css.ts) and for the HTML rules that close elements a page
// left open (a <p> before a <div>, a <td> before the next one), and writes
// the page straight into a small tree of boxes, text flows and tables that
// view.tsx turns into JSX.

import { addCss, backgroundOf, colorOf, lengthOf, matching, newSheet, parseDecls, resolveVars, sides, type El,
  type Sheet, type Vars } from './css'
import { MAX_SVG_TEXT, parseSvg, svgAspect, type SvgEl } from './svg'

// The first of a two-value shorthand (margin-block: 8px 0).
const split1 = (v: string) => v.trim().split(/\s+(?![^(]*\))/)[0]

// A text style, interned: equal styles are one object (view.tsx keys on it).
export type St = {
  size: number // CSS px
  color: string
  bold: boolean
  italic: boolean
  under: boolean
  strike: boolean
  mono: boolean
  pre: boolean
  wrap: boolean // pre-wrap: its spaces kept, its lines wrapped
  align: string // '', 'center', 'right'
  tt: string // text-transform: '', 'u'pper, 'l'ower, 'c'apitalize
  hidden: boolean // visibility: hidden
  key: string
}
// A run of a text flow: text (with its link `a`), a line break, a picture, a
// spacer (an empty picture: Hacker News indents its comments with one), a
// field or a form's button.
export type Run =
  | { x: string; s: St; a?: string }
  | { br: true; s?: St }
  | { img: string; w: number; h: number; alt: string; a?: string }
  | { svg: string; tree?: SvgEl; w: number; h: number; a?: string } // a linked SVG (its url), or one inline (its tree)
  | { sp: true; w: number; h: number }
  | { field: number; form: number; size: number; s: St; ph: string }
  | { btn: string; form: number; s: St }
export type Flow = { k: 't'; align: string; pre: boolean; runs: Run[] }
export type Box = {
  k: 'b'
  c: Node[]
  bg?: string
  pl?: number // CSS px of left indent
  pad?: number[] // CSS px of padding: top, right, bottom
  row?: { gap: number; justify: string } // a flex row: its children side by side
  aspect?: number // aspect-ratio: its height is its width over this
  mt?: number
  mb?: number
  w?: number // CSS px
  h?: number // CSS px, a minimum
  bar?: boolean // a blockquote's bar
  bgsvg?: string // an SVG picture it is filled with (a CSS background: Hacker News's vote arrows)
  mx?: number[] // such a picture's room to its left and right, CSS px
  mark?: string // a list item's bullet or number
  // a table cell's
  span?: number
  wpct?: number
  align?: string
  m?: any // view.tsx's measure, cached
}
export type Row = { bg?: string; h?: number; cells: Box[] }
// sp: the room between its cells (cellspacing, border-spacing), CSS px.
export type Table = { k: 'tab'; bg?: string; pad: number; sp?: number; full: boolean; border: boolean; rows: Row[]; m?: any }
export type Hr = { k: 'hr' }
export type Node = Box | Flow | Table | Hr
export type Field = { name: string; value: string; type: string }
export type Form = { action: string; fields: Field[] }
export type Page = {
  url: string
  title: string
  bg: string
  root: Box
  forms: Form[]
  svgs: string[] // the SVG pictures it links, to be downloaded
  truncated: boolean
  stats: { runs: number; images: number; links: number }
}

// viewport: the width the page is laid out at, in CSS pixels (@media, srcset).
// sheetUrls: where each of `sheets` came from (its url()s are against it).
// maxSvg: the shapes of inline SVG a page may have; maxSvgFiles: the SVG
// pictures it may link.
export type Options = { maxImages?: number; maxRuns?: number; sheets?: string[]; sheetUrls?: string[]; viewport?: number;
  maxSvg?: number; maxSvgFiles?: number }

// The picture of a srcset to fetch for `width` CSS pixels: the smallest that
// is as wide (a phone's choice, not a 4K screen's), else the widest; of
// density descriptors, 1x.
export function pickSrcset(srcset: string, width: number): string {
  let best = ''
  let bestW = 0
  let widest = ''
  let widestW = -1
  for (const item of srcset.split(/,\s+/)) {
    const [url, desc] = item.trim().split(/\s+/)
    if (!url) continue
    const w = desc && desc.endsWith('w') ? parseFloat(desc) : desc && desc.endsWith('x') ? parseFloat(desc) * width : width
    if (w >= width && (!best || w < bestW)) {
      best = url
      bestW = w
    }
    if (w > widestW) {
      widest = url
      widestW = w
    }
  }
  return best || widest
}

const VOID = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr',
  'keygen', 'frame', 'basefont', 'isindex',
])
// Raw text: read to their end tag without looking for tags inside.
const RAW = new Set(['script', 'style', 'textarea', 'title', 'xmp', 'noscript', 'iframe', 'noembed', 'noframes', 'plaintext',
  'svg'])
// Junk: dropped with everything inside.
const SKIP = new Set([
  'script', 'style', 'noscript', 'template', 'iframe', 'object', 'embed', 'video', 'audio', 'canvas', 'math',
  'select', 'datalist', 'map', 'noembed', 'noframes', 'frameset', 'head-skip', 'dialog', 'portal', 'slot',
])
const BLOCK = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'dd', 'details', 'dir', 'div', 'dl', 'dt', 'fieldset',
  'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'li', 'main',
  'menu', 'nav', 'ol', 'p', 'pre', 'section', 'summary', 'ul', 'legend', 'listing', 'xmp', 'search', 'caption',
])
// What closes an open <p>.
const P_CLOSERS = new Set([
  'address', 'article', 'aside', 'blockquote', 'center', 'details', 'dir', 'div', 'dl', 'fieldset', 'figcaption',
  'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav',
  'ol', 'p', 'pre', 'section', 'table', 'ul', 'li', 'dd', 'dt', 'search', 'listing', 'xmp',
])
// Elements whose end tag a page may leave out, and what ends them then.
const OPTIONAL_END = new Set(['li', 'p', 'td', 'th', 'tr', 'dt', 'dd'])
const CLOSES: Record<string, string[]> = {
  li: ['li'], p: [...P_CLOSERS], td: ['td', 'th', 'tr'], th: ['td', 'th', 'tr'], tr: ['tr'], dt: ['dt', 'dd'],
  dd: ['dt', 'dd'],
}
// What a skipped element of OPTIONAL_END may hold its own kind inside.
const NEST: Record<string, string[]> = {
  tr: ['table'], td: ['table'], th: ['table'], li: ['ul', 'ol', 'menu', 'dir'], dt: ['dl'], dd: ['dl'],
}
const HEADING: Record<string, number> = { h1: 2, h2: 1.5, h3: 1.17, h4: 1, h5: 0.83, h6: 0.67 }
const FONT_SIZES = [0, 10, 13, 16, 18, 24, 32, 48]
// Vertical margins, in em of the element's own size.
const MARGIN: Record<string, number> = {
  p: 1, h1: 0.67, h2: 0.83, h3: 1, h4: 1.33, h5: 1.67, h6: 2.33, ul: 1, ol: 1, dl: 1, blockquote: 1, pre: 1,
  figure: 1, menu: 1, dir: 1, hr: 0.5, fieldset: 0.5,
}
const ENTITIES: Record<string, string> = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', copy: '©', reg: '®', trade: '™', mdash: '—',
  ndash: '–', hellip: '…', laquo: '«', raquo: '»', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', sbquo: '‚',
  bdquo: '„', bull: '•', middot: '·', times: '×', divide: '÷', euro: '€', pound: '£', yen: '¥', cent: '¢',
  sect: '§', para: '¶', deg: '°', plusmn: '±', frac12: '½', frac14: '¼', frac34: '¾', sup2: '²', sup3: '³',
  larr: '←', rarr: '→', uarr: '↑', darr: '↓', harr: '↔', lArr: '⇐', rArr: '⇒', hearts: '♥', thinsp: ' ',
  ensp: ' ', emsp: ' ', zwnj: '', zwj: '', shy: '', lrm: '', rlm: '', iexcl: '¡', iquest: '¿',
  auml: 'ä', ouml: 'ö', uuml: 'ü', Auml: 'Ä', Ouml: 'Ö', Uuml: 'Ü', szlig: 'ß', eacute: 'é', egrave: 'è',
  ecirc: 'ê', aacute: 'á', agrave: 'à', acirc: 'â', iacute: 'í', oacute: 'ó', uacute: 'ú', ntilde: 'ñ',
  ccedil: 'ç', aring: 'å', oslash: 'ø', aelig: 'æ', Eacute: 'É', prime: '′', Prime: '″', minus: '−', le: '≤',
  ge: '≥', ne: '≠', infin: '∞', check: '✓', star: '☆',
}

export function decode(text: string): string {
  if (text.indexOf('&') < 0) return text
  return text.replace(/&(#[xX][0-9a-fA-F]{1,6}|#[0-9]{1,7}|[a-zA-Z][a-zA-Z0-9]{1,31})(;?)/g, (all, name, semi) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      if (!(code > 0) || code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return '�'
      return String.fromCodePoint(code === 0xa0 ? 0xa0 : code)
    }
    const value = ENTITIES[name]
    if (value === undefined) return all
    // Without a ";" only the old ones, as browsers read them.
    if (!semi && !/^(amp|lt|gt|quot|nbsp|copy|reg)$/.test(name)) return all
    return value
  })
}

// A URL against the page's, or '' for one this browser does not open.
export function resolve(href: string, base: string): string {
  const h = href.trim().replace(/[\t\n\r]/g, '')
  if (!h || h[0] === '#') return ''
  if (/^(https?:|mailto:|tel:)/i.test(h)) return h
  if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return '' // javascript:, data:, ...
  const m = /^(https?:)\/\/([^/?#]*)([^?#]*)(\?[^#]*)?/i.exec(base)
  if (!m) return ''
  const [, scheme, host] = m
  const basePath = m[3] || '/'
  if (h.startsWith('//')) return scheme + h
  if (h[0] === '/') return scheme + '//' + host + normalizePath(h)
  if (h[0] === '?') return scheme + '//' + host + basePath + h
  const dir = basePath.slice(0, basePath.lastIndexOf('/') + 1)
  return scheme + '//' + host + normalizePath(dir + h)
}

function normalizePath(path: string): string {
  const q = path.search(/[?#]/)
  const p = q < 0 ? path : path.slice(0, q)
  const rest = q < 0 ? '' : path.slice(q)
  const out: string[] = []
  const parts = p.split('/')
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    if (part === '..') {
      if (out.length > 1) out.pop()
    } else if (part !== '.') out.push(part)
  }
  const last = parts[parts.length - 1]
  if ((last === '.' || last === '..') && out[out.length - 1] !== '') out.push('')
  return out.join('/') + rest
}

// What a style sheet's name says it holds: the page's look (main, style,
// site, theme) before fonts, icons, code colors and widgets.
const SHEET_MAIN = /(^|[\/._-])(main|style|styles|site|theme|app|global|base|screen|common|index|bundle|layout|core)([._-]|$)/i
const SHEET_AUX = /(font|icon|print|gist|code|syntax|highlight|prism|katex|mathjax|emoji|vendor|cookie|consent|plugin|widget|button|pagination|comment|search|share|social|slider|carousel|swiper|lightbox|animate|dark|contrast|colorblind|tritanopia|dimmed|rtl)/i

// The stylesheets a page links (the three that look most like its own look,
// in the page's order), and its <base href>.
export function scanHead(html: string, url: string): { base: string; sheets: string[] } {
  const head = html.slice(0, 200000)
  let base = url
  const b = /<base\s[^>]*href\s*=\s*["']?([^"' >]+)/i.exec(head)
  if (b) base = resolve(decode(b[1]), url) || url
  const found: { url: string; rank: number; at: number }[] = []
  const re = /<link\s[^>]*>/gi
  let m: RegExpExecArray | null
  while ((m = re.exec(head)) && found.length < 40) {
    const tag = m[0]
    if (!/rel\s*=\s*["']?[^"'>]*\bstylesheet\b/i.test(tag)) continue
    if (/media\s*=\s*["']?(print|speech)/i.test(tag) || /\balternate\b/i.test(tag)) continue
    const href = /\shref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(tag)
    const abs = href ? resolve(decode(href[1] ?? href[2] ?? href[3] ?? ''), base) : ''
    if (!abs || !/^https?:/i.test(abs)) continue
    const path = abs.replace(/[?#].*$/, '').replace(/^https?:\/\/[^/]*/i, '')
    const rank = SHEET_MAIN.test(path.replace(/^.*\//, '')) ? 2 : SHEET_AUX.test(path) ? 0 : 1
    found.push({ url: abs, rank, at: found.length })
  }
  const chosen = found.slice().sort((x, y) => y.rank - x.rank || x.at - y.at).slice(0, 3)
  chosen.sort((x, y) => x.at - y.at)
  return { base, sheets: chosen.map((c) => c.url) }
}

type Kind = 'box' | 'table' | 'row' | 'inline' | 'form'
type Entry = {
  tag: string
  el: El
  st: St
  kind: Kind
  node?: Box | Table | Row
  flow?: Flow | null // a box's text flow still open
  href?: string
  form?: number // the GET form this is in, or -1 in a POST one
  list?: { ordered: boolean; n: number; none: boolean }
  btn?: { btn: string; form: number; s: St }
  apart?: boolean // an inline element with room after it (margin-right): words end there
  vars: Vars // custom properties, its parent's underneath
}

const BASE_STYLE = { size: 16, color: '#000000', bold: false, italic: false, under: false, strike: false, mono: false,
  pre: false, wrap: false, align: '', tt: '', hidden: false }

export function convert(html: string, url: string, options: Options = {}): Page {
  const maxImages = options.maxImages ?? 40
  const maxRuns = options.maxRuns ?? 30000
  const viewport = options.viewport ?? 640
  // No doctype: quirks mode, where a class or an id matches in any case.
  const quirks = !/<!doctype\s/i.test(html.slice(0, 2048))
  const fold = (name: string) => (quirks ? name.toLowerCase() : name)
  const classes = (text: string | undefined) => (text ? fold(text).trim().split(/\s+/) : [])
  const sheet: Sheet = newSheet(viewport, quirks)
  const { base } = scanHead(html, url)
  ;(options.sheets || []).forEach((css, i) => {
    const from = (options.sheetUrls || [])[i] || base
    addCss(sheet, css, (ref) => resolve(decode(ref), from))
  })
  let svgBudget = options.maxSvg ?? 4000
  const maxSvgFiles = options.maxSvgFiles ?? 6

  const styles = new Map<string, St>()
  const intern = (s: Omit<St, 'key'>): St => {
    const key = `${Math.round(s.size * 10) / 10}|${s.color}|${+s.bold}${+s.italic}${+s.under}${+s.strike}${+s.mono}${+s.pre}${+s.wrap}${+s.hidden}|${s.align}|${s.tt}`
    let st = styles.get(key)
    if (!st) styles.set(key, (st = { ...s, size: Math.round(s.size * 10) / 10, key }))
    return st
  }

  const root: Box = { k: 'b', c: [] }
  const page: Page = { url, title: '', bg: '', root, forms: [], svgs: [], truncated: false, stats: { runs: 0, images: 0, links: 0 } }
  // A linked SVG picture: listed to be downloaded, if there is room for it.
  const svgFile = (abs: string) => {
    if (page.svgs.indexOf(abs) >= 0) return true
    if (page.svgs.length >= maxSvgFiles) return false
    page.svgs.push(abs)
    return true
  }
  const stack: Entry[] = [
    { tag: 'html', el: { tag: 'html', id: '', cls: [], link: false }, st: intern(BASE_STYLE), kind: 'box', node: root, flow: null, form: undefined,
      vars: {} },
  ]
  const els: El[] = [stack[0].el]
  let htmlAttrs: Record<string, string> = {}
  const rootEntry = stack[0]
  // The <html> element's style (`:root`), over the browser's.
  const styleRoot = () => {
    const el: El = { tag: 'html', id: fold(htmlAttrs.id || ''), cls: classes(htmlAttrs.class), link: false,
      attrs: htmlAttrs }
    els.length = 1
    els[0] = el
    const look = styleFor("html", htmlAttrs, { ...rootEntry, st: intern(BASE_STYLE), vars: {} })
    stack[0].el = el
    stack[0].st = look.st
    stack[0].vars = look.vars
    if (look.bg) page.bg = look.bg
  }
  let runs = 0

  const top = () => stack[stack.length - 1]
  const push = (e: Entry) => {
    stack.push(e)
    els.push(e.el)
  }
  const popTo = (i: number) => {
    // Pops entries i.. off the stack.
    while (stack.length > i && stack.length > 1) {
      stack.pop()
      els.pop()
    }
  }
  const find = (pred: (e: Entry) => boolean, stop?: (e: Entry) => boolean): number => {
    for (let i = stack.length - 1; i > 0; i--) {
      if (pred(stack[i])) return i
      if (stop && stop(stack[i])) return -1
    }
    return -1
  }
  const tableScope = (e: Entry) => e.kind === 'table' || e.kind === 'row' || e.tag === 'td' || e.tag === 'th'
  const formOf = (): number | undefined => {
    for (let i = stack.length - 1; i >= 0; i--) if (stack[i].form !== undefined) return stack[i].form
    return undefined
  }
  // The link text is in; a link around a block (<a><div>…</div></a>) still
  // links what is in it.
  const hrefOf = (): string => {
    for (let i = stack.length - 1; i > 0; i--) if (stack[i].href !== undefined) return stack[i].href as string
    return ''
  }

  // The box that text and inline things go into: the nearest open box, or a
  // cell made for them where a table holds them directly.
  const sinkEntry = (): Entry => {
    for (let i = stack.length - 1; i >= 0; i--) {
      const e = stack[i]
      if (e.kind === 'box') return e
      if (e.kind === 'table' || e.kind === 'row') {
        popTo(i + 1)
        if (e.kind === 'table') openRow(e, {}, e.st)
        return openCell(top(), 'td', {}, top().st, true)
      }
    }
    return stack[0]
  }
  const flowOf = (e: Entry): Flow => {
    if (!e.flow) {
      e.flow = { k: 't', align: e.st.align, pre: e.st.pre, runs: [] }
      ;(e.node as Box).c.push(e.flow)
    }
    return e.flow
  }
  const endFlow = () => {
    for (let i = stack.length - 1; i >= 0; i--) {
      if (stack[i].kind === 'box') {
        stack[i].flow = null
        return
      }
    }
  }
  const addRun = (run: Run) => {
    if (runs >= maxRuns) {
      page.truncated = true
      return
    }
    runs++
    flowOf(sinkEntry()).runs.push(run)
  }

  const text = (raw: string) => {
    const t = top()
    if (t.btn) {
      t.btn.btn = (t.btn.btn + decode(raw)).replace(/\s+/g, ' ')
      return
    }
    let s = decode(raw)
    if (!t.st.pre) {
      s = s.replace(/[ \t\n\r\f]+/g, ' ')
      if (s === ' ') {
        // White space alone between table parts is nothing.
        if (t.kind === 'table' || t.kind === 'row') return
      }
    } else {
      s = s.replace(/\r\n?/g, '\n')
    }
    if (!s || t.st.hidden) return
    const e = sinkEntry()
    const flow = flowOf(e)
    const last = flow.runs[flow.runs.length - 1] as any
    if (!t.st.pre && s[0] === ' ' && (!last || last.br || (last.x !== undefined && last.x.endsWith(' ')))) {
      s = s.slice(1)
      if (!s) return
    }
    if (t.st.pre && !last && s[0] === '\n') s = s.slice(1)
    if (t.st.tt === 'u') s = s.toUpperCase()
    else if (t.st.tt === 'l') s = s.toLowerCase()
    else if (t.st.tt === 'c') s = s.replace(/(^|\s)(\S)/g, (all, sp, c) => sp + c.toUpperCase())
    const href = hrefOf()
    if (last && last.x !== undefined && last.s === t.st && (last.a || '') === href) {
      last.x += s
      return
    }
    const run: any = { x: s, s: t.st }
    if (href) {
      run.a = href
      page.stats.links++
    }
    addRun(run)
  }

  // The style an element gets: its parent's, the tag's own, its attributes,
  // the stylesheets' rules, then its style attribute.
  const styleFor = (tag: string, attrs: Record<string, string>, parent: Entry) => {
    const s: Omit<St, 'key'> = { ...parent.st }
    let bg = ''
    let display = BLOCK.has(tag) ? 'block' : ''
    let width = NaN
    let height = NaN
    let apart = 0 // bit 1: room before it, bit 2: after it
    switch (tag) {
      case 'b':
      case 'strong':
      case 'th':
        s.bold = true
        break
      case 'i':
      case 'em':
      case 'cite':
      case 'var':
      case 'dfn':
      case 'address':
        s.italic = true
        break
      case 'u':
      case 'ins':
        s.under = true
        break
      case 's':
      case 'strike':
      case 'del':
        s.strike = true
        break
      case 'code':
      case 'kbd':
      case 'samp':
      case 'tt':
        s.mono = true
        break
      case 'pre':
      case 'xmp':
      case 'listing':
        s.mono = true
        s.pre = true
        s.wrap = false
        break
      case 'small':
        s.size = parent.st.size / 1.2
        break
      case 'big':
        s.size = parent.st.size * 1.2
        break
      case 'sub':
      case 'sup':
        s.size = parent.st.size * 0.83
        break
      case 'center':
        s.align = 'center'
        break
      case 'a':
        if (attrs.href !== undefined) {
          s.color = '#0000ee'
          s.under = true
        }
        break
    }
    if (HEADING[tag]) {
      s.size = 16 * HEADING[tag] * (parent.st.size / 16)
      s.bold = true
    }
    if (tag === 'th') s.align = 'center'
    if (tag === 'font') {
      const c = colorOf(attrs.color)
      if (c) s.color = c
      const size = (attrs.size || '').trim()
      if (size) {
        let n = parseInt(size, 10)
        if (size[0] === '+' || size[0] === '-') n = 3 + n
        if (n > 0) s.size = FONT_SIZES[Math.min(7, Math.max(1, n))]
      }
    }
    if (attrs.align && /^(p|div|h[1-6]|td|th|tr|caption|center)$/.test(tag)) {
      const a = attrs.align.toLowerCase()
      s.align = a === 'center' || a === 'middle' ? 'center' : a === 'right' ? 'right' : a === 'left' ? '' : s.align
    }
    if (attrs.bgcolor) bg = colorOf(attrs.bgcolor)
    if (attrs.text && tag === 'body') s.color = colorOf(attrs.text) || s.color
    if (attrs.hidden !== undefined) display = 'none'
    if (attrs.width && /^\d+%$/.test(attrs.width.trim())) width = -parseInt(attrs.width, 10)
    else if (attrs.width && /^\d+(px)?$/.test(attrs.width.trim())) width = parseInt(attrs.width, 10)
    if (attrs.height && /^\d+(px)?$/.test(attrs.height.trim())) height = parseInt(attrs.height, 10)

    // Custom properties first (they cascade and inherit), then the rest with
    // their var()s worked out against them.
    const decls = matching(sheet, els)
    if (attrs.style) decls.push(parseDecls(attrs.style))
    let vars = parent.vars
    for (const d of decls) {
      for (const name in d) {
        if (name.charCodeAt(0) !== 45 || name.charCodeAt(1) !== 45) continue
        if (vars === parent.vars) vars = Object.create(parent.vars)
        vars[name] = d[name]
      }
    }
    const ps = parent.st
    let pad = [NaN, NaN, NaN, NaN]
    let mt = NaN
    let mb = NaN
    let ml = NaN
    let mr = NaN
    let off = 0 // placed off the page (a skip link above it, a menu slid out to its left)
    let spacing = NaN
    let listNone = false
    let srOnly = 0
    let flex = false
    let column = false
    let gap = NaN
    let justify = ''
    let aspect = 0
    let cover = false
    let bgsvg = ''
    const value = (d: Record<string, string>, name: string) => {
      const v = d[name]
      return v === undefined ? undefined : v.indexOf('var(') >= 0 ? resolveVars(v, vars).trim() : v
    }
    const inherits = (v: string) => v === 'inherit' || v === 'unset'
    const apply = (d: Record<string, string>) => {
      let v = value(d, 'color')
      if (v) s.color = inherits(v) || v === 'currentcolor' ? ps.color : v === 'initial' ? '#000000' : colorOf(v) || s.color
      const b = backgroundOf(value(d, 'background-color') || value(d, 'background'))
      if (b) bg = b === 'transparent' ? '' : b
      if ((v = value(d, 'background-image') || value(d, 'background'))) {
        const u = /url\(\s*["']?(https?:[^"')]+?\.svg(?:[?#][^"')]*)?)["']?\s*\)/i.exec(v)
        bgsvg = u ? u[1] : /url\(|none/.test(v) ? '' : bgsvg
      }
      if ((v = value(d, 'font-size'))) {
        const n = inherits(v) ? ps.size : lengthOf(v, ps.size)
        if (n > 0) s.size = n
      }
      if ((v = value(d, 'font'))) {
        const m = /(^|\s)([\d.]+(?:px|pt|em|rem|%))/.exec(v)
        if (m) {
          const n = lengthOf(m[2], ps.size)
          if (n > 0) s.size = n
        }
        if (/\b(bold|[6-9]00)\b/.test(v)) s.bold = true
        if (/\bmonospace\b/.test(v)) s.mono = true
      }
      if ((v = value(d, 'font-weight'))) {
        s.bold = inherits(v) ? ps.bold : v === 'bold' || v === 'bolder' || parseInt(v, 10) >= 600
      }
      if ((v = value(d, 'font-style'))) s.italic = inherits(v) ? ps.italic : /italic|oblique/.test(v)
      if ((v = value(d, 'font-family'))) {
        s.mono = inherits(v) ? ps.mono : /monospace|courier|consolas|menlo|mono\b/i.test(v.split(',')[0])
      }
      if ((v = value(d, 'text-decoration-line') || value(d, 'text-decoration'))) {
        s.under = inherits(v) ? ps.under : /underline/.test(v)
        s.strike = inherits(v) ? ps.strike : /line-through/.test(v)
      }
      if ((v = value(d, 'text-align'))) {
        s.align = inherits(v) ? ps.align : v === 'center' ? 'center' : v === 'right' || v === 'end' ? 'right' : ''
      }
      if ((v = value(d, 'text-transform'))) {
        s.tt = inherits(v) ? ps.tt : v === 'uppercase' ? 'u' : v === 'lowercase' ? 'l' : v === 'capitalize' ? 'c' : ''
      }
      if ((v = value(d, 'display'))) {
        flex = v === 'flex'
        if (v === 'none') display = 'none'
        else if (/^(block|flex|grid|list-item|flow-root|table)$/.test(v)) display = 'block'
        else if (/^(inline|inline-block|inline-flex|inline-grid|contents)$/.test(v)) display = ''
      }
      if ((v = value(d, 'flex-direction') || value(d, 'flex-flow'))) column = /column/.test(v)
      if ((v = value(d, 'gap') || value(d, 'column-gap'))) gap = lengthOf(v.split(/\s+/).pop(), s.size)
      if ((v = value(d, 'justify-content'))) {
        justify = /between|around|evenly/.test(v) ? 'between' : /center/.test(v) ? 'center' : /end|right/.test(v) ? 'end' : ''
      }
      if ((v = value(d, 'aspect-ratio'))) {
        const m = /^([\d.]+)\s*(?:\/\s*([\d.]+))?/.exec(v)
        aspect = m ? parseFloat(m[1]) / (m[2] ? parseFloat(m[2]) : 1) : 0
      }
      if ((v = value(d, 'object-fit'))) cover = v === 'cover'
      if ((v = value(d, 'visibility'))) s.hidden = v === 'hidden' || v === 'collapse'
      if ((v = value(d, 'white-space'))) {
        s.pre = /^pre|break-spaces/.test(v)
        s.wrap = /pre-wrap|pre-line|break-spaces/.test(v)
      }
      if ((v = value(d, 'width'))) {
        // A share of the box it is in, or a sum with one (calc(100% - 2rem)):
        // never of the font size.
        if (/^[\d.]+%$/.test(v)) width = -parseFloat(v)
        else if (v.indexOf('%') >= 0) width = /^calc\(\s*100%/.test(v) ? -100 : NaN
        else {
          const n = lengthOf(v, s.size)
          width = n >= 0 ? n : NaN
        }
      }
      if ((v = value(d, 'height'))) {
        const n = v.indexOf('%') >= 0 ? NaN : lengthOf(v, s.size)
        height = n >= 0 ? n : NaN
      }
      if ((v = value(d, 'list-style') || value(d, 'list-style-type'))) listNone = /\bnone\b/.test(v)
      // Text kept for screen readers alone (Tailwind's sr-only): clipped away.
      if ((v = value(d, 'clip')) && /rect\(0/.test(v)) srOnly |= 1
      if ((v = value(d, 'clip-path')) && /inset\(50%\)/.test(v)) srOnly |= 1
      if ((v = value(d, 'position')) && /absolute|fixed/.test(v)) srOnly |= 2
      // Padding and the top margin, in CSS pixels.
      if ((v = value(d, 'padding'))) pad = sides(v, s.size)
      if ((v = value(d, 'padding-block'))) pad[0] = pad[2] = sides(v, s.size)[0]
      if ((v = value(d, 'padding-inline'))) pad[1] = pad[3] = sides(v, s.size)[1]
      for (const [name, side] of [['padding-top', 0], ['padding-right', 1], ['padding-bottom', 2], ['padding-left', 3],
        ['padding-inline-start', 3], ['padding-inline-end', 1]] as [string, number][]) {
        if ((v = value(d, name))) pad[side] = lengthOf(v, s.size)
      }
      if ((v = value(d, 'margin'))) {
        const m = sides(v, s.size)
        mt = m[0]
        mb = m[2]
        mr = m[1]
        ml = m[3]
      }
      if ((v = value(d, 'margin-left') || value(d, 'margin-inline-start'))) ml = lengthOf(v, s.size)
      if ((v = value(d, 'margin-right') || value(d, 'margin-inline-end'))) mr = lengthOf(v, s.size)
      if ((v = value(d, 'margin-block'))) {
        const m = sides(v, s.size)
        mt = m[0]
        mb = m[2]
      }
      if ((v = value(d, 'margin-block-start') || value(d, 'margin-top'))) mt = lengthOf(split1(v), s.size)
      if ((v = value(d, 'margin-block-end') || value(d, 'margin-bottom'))) mb = lengthOf(split1(v), s.size)
      for (let side = 0; side < 2; side++) {
        if ((v = value(d, side ? 'left' : 'top'))) {
          const far = v[0] === '-' && (/%$/.test(v) ? parseFloat(v) <= -50 : lengthOf(v, s.size) <= -30)
          off = far ? off | (1 << side) : off & ~(1 << side)
        }
      }
      if ((v = value(d, 'transform') || value(d, 'translate'))) {
        off = /^(translate[xy3d]*\()?\s*-(\d{3,}|[5-9]\d)(\.\d*)?%/i.test(v) ? off | 4 : off & ~4
      }
      if ((v = value(d, 'border-collapse'))) spacing = v === 'collapse' ? 0 : spacing
      if ((v = value(d, 'border-spacing'))) spacing = lengthOf(split1(v), s.size)
      const left = value(d, 'margin-left') || value(d, 'margin-inline-start') || value(d, 'padding-left')
      if (left !== undefined && lengthOf(left, s.size) >= 3) apart |= 1
      const right = value(d, 'margin-right') || value(d, 'margin-inline-end') || value(d, 'padding-right')
      if (right !== undefined && lengthOf(right, s.size) >= 3) apart |= 2
    }
    for (const d of decls) apply(d)
    if (srOnly === 3 || (srOnly & 2 && ((width >= 0 && width <= 1 && height >= 0 && height <= 1) || off))) display = 'none'
    const row = flex && !column ? { gap: gap >= 0 ? Math.min(gap, 64) : 0, justify } : null
    return { st: intern(s), bg, bgsvg, display, width, height, pad, mt, mb, ml, mr, spacing, listNone, apart, vars, row, abs: (srOnly & 2) !== 0,
      aspect: aspect > 0.1 && aspect < 10 ? aspect : 0, cover }
  }

  const openRow = (table: Entry, attrs: Record<string, string>, st: St, bg = '', height = NaN) => {
    const row: Row = { cells: [] }
    if (bg) row.bg = bg
    if (height > 0) row.h = height
    ;(table.node as Table).rows.push(row)
    push({ tag: 'tr', el: { tag: 'tr', id: '', cls: [], link: false }, st, kind: 'row', node: row, vars: table.vars })
  }
  const openCell = (row: Entry, tag: string, attrs: Record<string, string>, st: St, implicit = false,
    bg = '', width = NaN, height = NaN): Entry => {
    const cell: Box = { k: 'b', c: [] }
    const span = parseInt(attrs.colspan || '1', 10)
    if (span > 1) cell.span = Math.min(span, 50)
    if (bg) cell.bg = bg
    if (width > 0) cell.w = width
    else if (width < 0) cell.wpct = -width
    if (height > 0) cell.h = height
    ;(row.node as Row).cells.push(cell)
    const e: Entry = { tag, el: implicit ? { tag, id: '', cls: [], link: false } : row.el, st, kind: 'box', node: cell,
      flow: null, vars: row.vars }
    if (!implicit) e.el = { tag, id: '', cls: [], link: false }
    push(e)
    return e
  }

  let skip = '' // the tag a skipped subtree started with
  let skipDepth = 0
  let skipNest = 0 // tables (lists) opened inside a skipped cell or row (item)

  const startTag = (tag: string, attrs: Record<string, string>, raw: string | null) => {
    if (skip) {
      // A hidden <li>, <p> or cell the page never closed ends at the next one,
      // but not at one of a table (list) inside it: Hacker News hides a
      // collapsed comment's row, which holds a table of its own.
      const scope = NEST[skip]
      if (scope && scope.includes(tag)) {
        skipNest++
        return
      }
      if (skipNest > 0 || !(OPTIONAL_END.has(skip) && (tag === skip || CLOSES[skip]?.includes(tag)))) {
        if (tag === skip && skipNest === 0) skipDepth++
        return
      }
      skip = ''
    }
    if (SKIP.has(tag) || (tag === 'input' && (attrs.type || '').toLowerCase() === 'hidden')) {
      if (tag === 'input') {
        const form = formOf()
        if (form !== undefined && form >= 0 && attrs.name) {
          page.forms[form].fields.push({ name: attrs.name, value: decode(attrs.value || ''), type: 'hidden' })
        }
        return
      }
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
        skipNest = 0
      }
      return
    }
    if (tag === 'html') {
      htmlAttrs = attrs
      styleRoot()
      return
    }
    if (tag === 'head' || tag === 'tbody' || tag === 'thead' || tag === 'tfoot' || tag === 'colgroup' || tag === 'col'
      || tag === 'meta' || tag === 'link' || tag === 'base' || tag === 'wbr' || tag === 'source' || tag === 'track'
      || tag === 'param' || tag === 'area' || tag === 'picture') {
      return
    }

    // The HTML rules that close what a page left open.
    if (P_CLOSERS.has(tag)) {
      const p = find((e) => e.tag === 'p', tableScope)
      if (p > 0) popTo(p)
    }
    if (tag === 'li') {
      const li = find((e) => e.tag === 'li', (e) => tableScope(e) || e.tag === 'ul' || e.tag === 'ol')
      if (li > 0) popTo(li)
    } else if (tag === 'dt' || tag === 'dd') {
      const d = find((e) => e.tag === 'dt' || e.tag === 'dd', (e) => tableScope(e) || e.tag === 'dl')
      if (d > 0) popTo(d)
    } else if (tag === 'a') {
      const a = find((e) => e.tag === 'a', tableScope)
      if (a > 0) popTo(a)
    } else if (HEADING[tag] && HEADING[top().tag]) {
      popTo(stack.length - 1)
    } else if (tag === 'button') {
      const b = find((e) => e.tag === 'button', tableScope)
      if (b > 0) popTo(b)
    }

    // Table parts go where their table is, whatever was left open in it.
    if (tag === 'tr') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    } else if (tag === 'td' || tag === 'th') {
      const r = find((e) => e.kind === 'row' || e.kind === 'table')
      if (r < 0) return
      popTo(r + 1)
      if (stack[r].kind === 'table') openRow(stack[r], {}, stack[r].st)
    } else if (tag === 'caption') {
      const t = find((e) => e.kind === 'table')
      if (t < 0) return
      popTo(t + 1)
    }

    const parent = top()
    const el: El = {
      tag,
      id: fold(attrs.id || ''),
      cls: classes(attrs.class),
      link: tag === 'a' && attrs.href !== undefined,
      attrs,
    }
    els.push(el)
    const look = styleFor(tag, attrs, parent)
    els.pop()
    if (look.display === 'none') {
      if (!VOID.has(tag) && raw === null) {
        skip = tag
        skipDepth = 1
        skipNest = 0
      }
      return
    }
    const st = look.st
    // A form that posts (a login, a comment box) cannot be sent from here, and
    // a javascript: link does nothing without its script: both are dropped.
    if ((tag === 'form' && (attrs.method || '').toLowerCase() === 'post') ||
      (tag === 'a' && /^\s*javascript:/i.test(attrs.href || ''))) {
